-- Bolton Vouched: Venetian plaster and vehicle recovery (two new trades) for the LIVE Supabase project
-- (mmarznvndvbwyhhtbfjy).
-- Paste ALL of this into Supabase -> SQL Editor -> New query -> Run, once. It is one transaction: if anything
-- fails, nothing is changed. Confirm the 'destructive operation' warning (it comes from 'create or replace' and
-- 'drop ... if exists' lines; no data is deleted). The checks at the end fail the whole paste if a piece is missing.
-- Generated by scripts/build-production-sql.mjs from supabase/migrations/20261012000044_venetian_plaster_recovery.sql .. 20261012000044_venetian_plaster_recovery.sql;
-- do not edit by hand.
begin;

-- Run the check numbers script (docs/launch/check-numbers-production.sql) first: this stops (changing nothing) if it hasn't been.
do $requires$
begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012000043') then
    raise exception 'Run the check numbers script (docs/launch/check-numbers-production.sql) first: migration 20261012000043 is not recorded';
  end if;
end
$requires$;

-- ==== 20261012000044_venetian_plaster_recovery.sql
-- Two more trades requested by the owner: Venetian plaster (Home & trades: polished and decorative plaster, a
-- specialist finish most plasterers don't offer) and vehicle recovery (Vehicles), with the check that matters: agree
-- the price before they set off, and that they're insured to carry your vehicle. Roofers and bricklayers were already
-- listed (Roofer, Bricklayer); only their search words change, in the app.
-- Idempotent: safe to run again.
insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, v.slug, v.name, 'none'::public.category_requirement, v.note
from (values
  ('home-trades', 'venetian-plaster', 'Venetian plaster', null),
  ('vehicles', 'vehicle-recovery', 'Vehicle recovery',
   'Agree the price before they set off (recovery is often charged by distance), and ask if they have goods-in-transit insurance to cover your vehicle while it''s on their truck.')
) as v(grp, slug, name, note)
join public.category_groups g on g.slug = v.grp
on conflict (slug) do nothing;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000044', 'venetian_plaster_recovery') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
begin
  if (select count(*) from public.categories c join public.category_groups g on g.id = c.group_id
      where c.active and ((c.slug = 'venetian-plaster' and g.slug = 'home-trades')
                       or (c.slug = 'vehicle-recovery' and g.slug = 'vehicles'))) <> 2 then
    raise exception 'Venetian plaster and vehicle recovery check failed: one of the two trades is missing';
  end if;
end
$verify$;

commit;

select 'Venetian plaster and vehicle recovery applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000044')) as migrations_recorded;
